import json
from pathlib import Path
p=Path('PCB');plan=json.loads((p/'manifests/revision-v05.json').read_text(encoding='utf-8'));spec=[]
for i,z in enumerate(plan['leds']):
 col=0 if i<3 else 1 if i<6 else 2;row=i%3 if i<6 else i-6;x=180+col*300;y=650-row*200
 spec.extend([{'ref':z['diode'],'x':x,'y':y+({'red':8,'green':0,'blue':7}[z['color']])},{'ref':z['resistor'],'x':x+100,'y':y}])
for batch in range(3):
 code='''if((await eda.dmt_Project.getCurrentProjectInfo())?.uuid!=="b7122aadd3e496b681150192bfbef370394a2ba91164cb1621df30a137bdfaf5")throw Error("Wrong project");await eda.dmt_EditorControl.openDocument("8ecd39430ee2c9d6");const spec='''+json.dumps(spec[batch*6:(batch+1)*6])+''';const map='''+json.dumps(plan['expected'])+''';for(const z of spec){const old=(await eda.sch_PrimitiveComponent.getAll("part")).find(c=>c.getState_Designator()===z.ref);if(!old)throw Error(z.ref);if(old.getState_X()===z.x&&old.getState_Y()===z.y)continue;const uid=old.getState_UniqueId();const c=await eda.sch_PrimitiveComponent.create({libraryUuid:"b7122aadd3e496b681150192bfbef370394a2ba91164cb1621df30a137bdfaf5",uuid:old.getState_Component().uuid},z.x,z.y,undefined,0,false,true,true);if(!c)throw Error("Recreate failed");const wires=await eda.sch_PrimitiveWire.getAll();const ids=new Set();for(const pin of await old.getAllPins()){for(const w of wires){const l=w.getState_Line();const paths=Array.isArray(l[0])?l:[l];if(paths.some(l=>{for(let i=0;i<l.length;i+=2)if(Math.abs(l[i]-pin.getState_X())<.001&&Math.abs(l[i+1]-pin.getState_Y())<.001)return true;return false;}))ids.add(w.getState_PrimitiveId());}}if(ids.size)await eda.sch_PrimitiveWire.delete([...ids]);await eda.sch_PrimitiveComponent.delete(old.getState_PrimitiveId());const a=c.toAsync();a.setState_Designator(z.ref);a.setState_UniqueId(uid);await a.done();for(const q of await c.getAllPins()){const x=q.getState_X(),y=q.getState_Y(),r=q.getState_Rotation(),net=map[z.ref][q.getState_PinNumber()];if(!await eda.sch_PrimitiveWire.create([x,y,x+Math.round(Math.cos(r*Math.PI/180))*20,y+Math.round(Math.sin(r*Math.PI/180))*20],net))throw Error("Reconnect failed");}}return {saved:await eda.sch_Document.save()};'''
 (p/f'scripts/align-leds-v05-{batch+1}.js').write_text(code,encoding='utf-8')

